import{_ as i,C as e,o,c as l,E as a,a2 as c}from"./chunks/framework.BOeh4kYD.js";const s="/joinwell52/assets/authority-scope-20260910/02-concurrency-domain.figure.zh.png",A=JSON.parse('{"title":"并发上限设为 1，为什么两个任务仍能同时运行？","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"并发上限设为 1，为什么两个任务仍能同时运行？","date":"2026-09-10","published_date":"2026-09-10","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"并发上限设为 1，为什么两个任务仍能同时运行？","summary":"AG2 的原方法对照实验揭示两件不同的事：循环内超限可以被修复，而整个 Agent 的总额度仍需要另一份明确合同。","cover":"/assets/authority-scope-20260910/02-concurrency-domain.cover-v1.png","language":"zh-CN","lifecycle":"Published","publication_authorized":true,"evidence_status":"固定源码的有界接缝实验；非完整系统验证","pageClass":"authority-scope-article"},"headers":[],"relativePath":"zh/engineering/2026-09-10-concurrency-domain.md","filePath":"zh/engineering/2026-09-10-concurrency-domain.md","lastUpdated":1789010602000}'),d={name:"zh/engineering/2026-09-10-concurrency-domain.md"};function g(h,t,p,u,m,y){const r=e("ArticleCover"),n=e("ArticleTableScroll");return o(),l("div",null,[a(r,{image:"/assets/authority-scope-20260910/02-concurrency-domain.cover-v1.png",kicker:"开源工程观察 · 实验研究",title:"并发上限设为 1，为什么两个任务仍能同时运行？",summary:"AG2 的原方法对照实验揭示两件不同的事：循环内超限可以被修复，而整个 Agent 的总额度仍需要另一份明确合同。",version:"2026-09-10",languageHref:"/en/engineering/2026-09-10-concurrency-domain",languageLabel:"English"}),a(n,{language:"zh"}),t[0]||(t[0]=c('<h1 id="并发上限设为-1-为什么两个任务仍能同时运行" tabindex="-1">并发上限设为 1，为什么两个任务仍能同时运行？ <a class="header-anchor" href="#并发上限设为-1-为什么两个任务仍能同时运行" aria-label="Permalink to &quot;并发上限设为 1，为什么两个任务仍能同时运行？&quot;">​</a></h1><p>假设一个 Agent 的配置写着 <code>max_concurrency=1</code>。两个线程同时使用这个 Agent，最终有两个任务在运行。它违反配置了吗？</p><p>如果“1”属于整个 Agent，答案是违反。如果每个线程中的事件循环各有一份额度，两项任务可以同时运行，而且都遵守了各自的限制。</p><p>这不是文字游戏。同一个数字，可以保护一次 API 调用的成本，也可以只是安排单个事件循环里的工作。工程审查若不先问“这个上限属于谁”，很容易把局部修复误读成全局保证。</p><h2 id="先把真正的错误复现出来" tabindex="-1">先把真正的错误复现出来 <a class="header-anchor" href="#先把真正的错误复现出来" aria-label="Permalink to &quot;先把真正的错误复现出来&quot;">​</a></h2><p>AG2 是一个构建和编排 Agent 的开源框架。<a href="https://github.com/ag2ai/ag2/pull/3243" target="_blank" rel="noreferrer">PR #3243</a>修复子任务准入时的信号量缓存。信号量可以理解为可借出的有限名额：名额用完，后来的协程等待；任务结束，名额归还。</p><p>旧方法把信号量和它所属的事件循环保存在同一个 Agent 的两个字段里。遇到另一个循环时，就重新创建一份。多个 OS 线程交替使用同一个 Agent，可能不断替换这份缓存。先前已有任务占用的名额没有消失，但新请求开始拿另一份全新的名额。</p><p>我们固定修复前后源码，抽取原始 <code>_spawn_subtask</code> 方法运行。任务正文被替换成等待释放的计数协程，不调用模型。为了避免把能否复现交给运气，实验明确安排了一个交错：</p><ol><li>循环 A 的第一个任务 A1 进入，占住一个名额。</li><li>另一个真实线程中的循环 B 启动 B1。</li><li>A1 和 B1 都未结束，循环 A 再申请 A2。</li><li>记录各循环和整体在途峰值，最后统一释放。</li></ol><p>旧代码下，A2 又获得一份新名额。A 自己同时运行两个任务，整个实验同时运行三个。这已经超过“每循环 1”的较窄解释，是明确的局部额度失效。</p><h2 id="修复后-哪个数字变成了-1" tabindex="-1">修复后，哪个数字变成了 1？ <a class="header-anchor" href="#修复后-哪个数字变成了-1" aria-label="Permalink to &quot;修复后，哪个数字变成了 1？&quot;">​</a></h2><p>候选修复为每个运行中的事件循环保存自己的信号量，并用线程锁保护查询和创建。循环 B 不再覆盖循环 A 的那份额度。相同交错中，A2 等待 A1 释放，局部错误消失。</p><table tabindex="0"><thead><tr><th>代码版本与输入</th><th style="text-align:right;">A 循环峰值</th><th style="text-align:right;">B 循环峰值</th><th style="text-align:right;">全局峰值</th></tr></thead><tbody><tr><td>修复前，单循环</td><td style="text-align:right;">1</td><td style="text-align:right;">0</td><td style="text-align:right;">1</td></tr><tr><td>修复前，双循环</td><td style="text-align:right;">2</td><td style="text-align:right;">1</td><td style="text-align:right;">3</td></tr><tr><td>候选修复，单循环</td><td style="text-align:right;">1</td><td style="text-align:right;">0</td><td style="text-align:right;">1</td></tr><tr><td>候选修复，双循环</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td style="text-align:right;">2</td></tr></tbody></table><p>每种配置每轮运行五次，两轮共四十次受控试验，逐次结果一致，没有异常。我们同时统计局部和全局，是为了让“修好了”对应到具体承诺：所测交错下，新方法维护了每循环上限，双循环合计仍为二。</p><p><img src="'+s+'" alt="同一实验的局部峰值与全局峰值"></p><p><em>图 1：图中是等待型合成子任务的在途数，不是模型请求数、吞吐量或费用测量。 来源：本轮固定源码实验的第 1、2 轮保存观测。</em></p><p>上游新增测试也明确检查每个循环的上限。因此，合计为二不应被命名为“修复仍然失效”。它是另一份合同尚未被这项修复提供的证据。善意、准确地指出这个区别，比把正常的分域行为包装成安全漏洞更有价值。</p><h2 id="从一个数字-补成一个可验收的约束" tabindex="-1">从一个数字，补成一个可验收的约束 <a class="header-anchor" href="#从一个数字-补成一个可验收的约束" aria-label="Permalink to &quot;从一个数字，补成一个可验收的约束&quot;">​</a></h2><p>当这个配置用于限制真实资源时，评审至少要说清四件事。</p><p>第一是<strong>额度所属范围</strong>：单循环、单 Agent、单进程、单宿主，还是整个租户？第二是<strong>谁有权发放额度</strong>：一份内存对象，还是所有执行者共享的计数服务？第三是<strong>额度持续多久</strong>：任务返回、进程退出、租约到期或人工清理，分别意味着什么？第四是<strong>发生不确定性时怎么处理</strong>：旧任务失联，不应仅因观察不到就默认归还它可能仍在占用的名额。</p><p>例如，一个用户把上限设为一，是为了避免两个昂贵任务同时消耗同一个账户。实现若按循环分别发放名额，即使每个循环的测试全绿，也可能没有满足用户的预算意图。反过来，产品若明确承诺每循环一项，就不该为了追求“更安全”的宣传，未经设计把它改成跨域串行，损失本来允许的并行能力。</p><p>这里的改进起点是合同：先决定上限保护什么，再选择锁、共享计数或租约。增加一把线程锁，只能解决它实际保护的那次读写；不会自动把独立计数器变成同一份资源事实。</p><h2 id="这次实验没有证明什么" tabindex="-1">这次实验没有证明什么 <a class="header-anchor" href="#这次实验没有证明什么" aria-label="Permalink to &quot;这次实验没有证明什么&quot;">​</a></h2><p>我们没有运行完整 AG2 Agent、工具链或模型服务，也没有测试多进程、多宿主、跨租户预算。初始化状态是按版本设置的测试替身，实际执行的是固定源码里的原准入方法。该 PR 在核查时仍为 Open，不能写成所有用户已经获得修复。</p><p>它给出的可复用检查却很简单：<strong>除了“峰值是否超过上限”，还要断言“在哪个范围统计这个峰值”。</strong> 一个没有对象范围的上限，既难被实现，也难被公平地验收。</p><p><a href="/joinwell52/en/engineering/2026-09-10-concurrency-domain">English</a> · <a href="/joinwell52/zh/research/evidence/2026-09-10-authority-scope">实验方法、固定版本与逐轮结果</a></p>',26))])}const x=i(d,[["render",g]]);export{A as __pageData,x as default};
